import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './ProfileSettingsPage.css';

const ProfileSettingsPage = ({ user, onUpdate }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nickname: '',
    description: '',
    avatar: ''
  });
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showProjectForm, setShowProjectForm] = useState(false);
  const [projectForm, setProjectForm] = useState({
    title: '',
    description: ''
  });
  const [selectedProject, setSelectedProject] = useState(null);
  const [projectFiles, setProjectFiles] = useState([]);
  const [uploadingFile, setUploadingFile] = useState(false);

  useEffect(() => {
    if (user) {
      setFormData({
        nickname: user.nickname || '',
        description: user.description || '',
        avatar: user.avatar || ''
      });
      fetchProjects();
    }
  }, [user]);

  const fetchProjects = async () => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await axios.get('/api/projects', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setProjects(response.data);
    } catch (error) {
      console.error('Ошибка загрузки проектов:', error);
    }
  };

  const fetchProjectFiles = async (projectId) => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await axios.get(`/api/projects/${projectId}/files`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setProjectFiles(response.data);
    } catch (error) {
      console.error('Ошибка загрузки файлов проекта:', error);
      setError('Ошибка загрузки файлов проекта');
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleProjectFormChange = (e) => {
    const { name, value } = e.target;
    setProjectForm(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const token = localStorage.getItem('access_token');
      const response = await axios.put('/api/users/profile', formData, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      setSuccess('Профиль успешно обновлен');
      if (onUpdate) {
        onUpdate(response.data);
      }
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка обновления профиля');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateProject = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const token = localStorage.getItem('access_token');
      await axios.post('/api/projects', projectForm, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      setProjectForm({ title: '', description: '' });
      setShowProjectForm(false);
      fetchProjects();
      setSuccess('Проект создан');
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка создания проекта');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteProject = async (projectId) => {
    if (!window.confirm('Вы уверены, что хотите удалить этот проект?')) {
      return;
    }

    try {
      const token = localStorage.getItem('access_token');
      await axios.delete(`/api/projects/${projectId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      fetchProjects();
      setSuccess('Проект удален');
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка удаления проекта');
    }
  };

  const handleAvatarUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData(prev => ({
          ...prev,
          avatar: event.target.result
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file || !selectedProject) return;

    // Получаем расширение файла
    const fileName = file.name.toLowerCase();
    const allowedExtensions = ['.png', '.jpg', '.jpeg', '.webp', '.css', '.html', '.htm', '.js'];
    const fileExtension = fileName.substring(fileName.lastIndexOf('.'));

    if (!allowedExtensions.includes(fileExtension)) {
      setError('Неподдерживаемый формат файла. Разрешены: PNG, JPEG, WebP, CSS, HTML, JS');
      return;
    }

    // Проверяем размер файла (10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError('Размер файла превышает 10MB');
      return;
    }

    setUploadingFile(true);
    setError('');

    try {
      const formData = new FormData();
      formData.append('file', file);

      const token = localStorage.getItem('access_token');
      await axios.post(`/api/projects/${selectedProject.id}/files`, formData, {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      fetchProjectFiles(selectedProject.id);
      setSuccess('Файл загружен успешно');
      // Очищаем input
      e.target.value = '';
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка загрузки файла');
      // Очищаем input при ошибке
      e.target.value = '';
    } finally {
      setUploadingFile(false);
    }
  };

  const handleFileDownload = async (file) => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await axios.get(`/api/projects/${selectedProject.id}/files/${file.id}/download`, {
        headers: { 'Authorization': `Bearer ${token}` },
        responseType: 'blob'
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', file.original_filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      setError('Ошибка скачивания файла');
    }
  };

  const handleFileDelete = async (fileId) => {
    if (!window.confirm('Вы уверены, что хотите удалить этот файл?')) {
      return;
    }

    try {
      const token = localStorage.getItem('access_token');
      await axios.delete(`/api/projects/${selectedProject.id}/files/${fileId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      fetchProjectFiles(selectedProject.id);
      setSuccess('Файл удален');
    } catch (error) {
      setError(error.response?.data?.detail || 'Ошибка удаления файла');
    }
  };

  const openProjectFiles = (project) => {
    setSelectedProject(project);
    fetchProjectFiles(project.id);
  };

  const closeProjectFiles = () => {
    setSelectedProject(null);
    setProjectFiles([]);
  };

  if (!user) {
    return (
      <div className="settings-page">
        <div className="settings-error">
          <h2>Доступ запрещен</h2>
          <p>Для доступа к настройкам необходимо войти в систему.</p>
          <button className="btn btn-primary" onClick={() => navigate('/')}>
            На главную
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="settings-page">
      <div className="settings-container">
        <div className="settings-header">
          <button className="back-btn" onClick={() => navigate(`/profile/${user.unique_id}`)}>
            ← К профилю
          </button>
          <h1>Настройки профиля</h1>
        </div>

        <div className="settings-content">
          {error && <div className="alert alert-error">{error}</div>}
          {success && <div className="alert alert-success">{success}</div>}

          <form onSubmit={handleSubmit} className="profile-form">
            <h2>Основная информация</h2>

            <div className="form-group">
              <label>Никнейм</label>
              <input
                type="text"
                name="nickname"
                value={formData.nickname}
                onChange={handleInputChange}
                required
                maxLength={20}
              />
            </div>

            <div className="form-group">
              <label>Описание</label>
              <textarea
                name="description"
                value={formData.description}
                onChange={handleInputChange}
                rows={4}
                placeholder="Расскажите о себе..."
              />
            </div>

            <div className="form-group">
              <label>Аватарка</label>
              <div className="avatar-upload">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleAvatarUpload}
                  id="avatar-upload"
                  style={{ display: 'none' }}
                />
                <label htmlFor="avatar-upload" className="avatar-upload-btn">
                  {formData.avatar ? (
                    <img src={formData.avatar} alt="Аватар" />
                  ) : (
                    <div className="default-avatar">
                      {formData.nickname.charAt(0).toUpperCase()}
                    </div>
                  )}
                  <span>Изменить аватар</span>
                </label>
              </div>
            </div>

            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Сохранение...' : 'Сохранить изменения'}
            </button>
          </form>

          <div className="projects-section">
            <div className="projects-header">
              <h2>Мои проекты ({projects.length})</h2>
              <button 
                className="btn btn-secondary"
                onClick={() => setShowProjectForm(!showProjectForm)}
              >
                {showProjectForm ? 'Отмена' : 'Добавить проект'}
              </button>
            </div>

            {showProjectForm && (
              <form onSubmit={handleCreateProject} className="project-form">
                <div className="form-group">
                  <label>Название проекта</label>
                  <input
                    type="text"
                    name="title"
                    value={projectForm.title}
                    onChange={handleProjectFormChange}
                    required
                    maxLength={100}
                  />
                </div>
                <div className="form-group">
                  <label>Описание</label>
                  <textarea
                    name="description"
                    value={projectForm.description}
                    onChange={handleProjectFormChange}
                    rows={3}
                    placeholder="Описание проекта..."
                  />
                </div>
                <button type="submit" className="btn btn-primary" disabled={loading}>
                  Создать проект
                </button>
              </form>
            )}

            <div className="projects-list">
              {projects.map((project) => (
                <div key={project.id} className="project-item">
                  <div className="project-info">
                    <h3>{project.title}</h3>
                    {project.description && <p>{project.description}</p>}
                    <small>Создан {new Date(project.created_at).toLocaleDateString('ru-RU')}</small>
                    {project.files && project.files.length > 0 && (
                      <small className="files-count">Файлов: {project.files.length}</small>
                    )}
                  </div>
                  <div className="project-actions">
                    <button
                      className="btn btn-secondary btn-sm"
                      onClick={() => openProjectFiles(project)}
                    >
                      Файлы
                    </button>
                    <button
                      className="btn btn-danger btn-sm"
                      onClick={() => handleDeleteProject(project.id)}
                    >
                      Удалить
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {selectedProject && (
              <div className="project-files-modal">
                <div className="project-files-content">
                  <div className="project-files-header">
                    <h3>Файлы проекта: {selectedProject.title}</h3>
                    <button className="close-btn" onClick={closeProjectFiles}>×</button>
                  </div>

                  <div className="file-upload-section">
                    <input
                      type="file"
                      id="file-upload"
                      onChange={handleFileUpload}
                      accept=".png,.jpg,.jpeg,.webp,.css,.html,.htm,.js"
                      style={{ display: 'none' }}
                      disabled={uploadingFile}
                    />
                    <label htmlFor="file-upload" className="btn btn-primary">
                      {uploadingFile ? 'Загрузка...' : 'Загрузить файл'}
                    </label>
                    <small className="upload-hint">
                      Разрешены: PNG, JPEG, WebP, CSS, HTML, JS (до 10MB)
                    </small>
                  </div>

                  <div className="files-list">
                    {projectFiles.length === 0 ? (
                      <p className="no-files">Файлы не загружены</p>
                    ) : (
                      projectFiles.map((file) => (
                        <div key={file.id} className="file-item">
                          <div className="file-info">
                            <span className="file-name">{file.original_filename}</span>
                            <span className="file-size">
                              {(file.file_size / 1024).toFixed(1)} KB
                            </span>
                            <span className="file-type">{file.content_type}</span>
                          </div>
                          <div className="file-actions">
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => handleFileDownload(file)}
                            >
                              Скачать
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleFileDelete(file.id)}
                            >
                              Удалить
                            </button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProfileSettingsPage;
